export declare const USAGE = "Usage: agentflow-app <command> [options]\n\nCommands:\n  init <dir> --prefix <prefix> [--key <key>] [--no-ui] [--no-site]\n                                      start an app in <dir> from the starter; the key defaults to the folder's name\n  init <dir> --from <draft.zip>       start an app in <dir> from a draft downloaded from Admin \u2192 Apps \u2192 Pack\n  build [--check]                     write package/ from the app's config; --check only compares\n  build --check --values              compare as JSON values, member order aside, as when rewriting a converted workflow\n  keygen --key-id <id> [--out <file>] make a signing key (default keys/<id>.pem) and print where it is\n  seal [--key <file>] [--key-id <id>] [--out <dir>]\n                                      sign package/ into <out>/<package>-<version>.afpkg (default dist-app/)\n  lint [--url <url>]                  send package/ to AgentFlow and print the problems it finds\n  deploy [--file <afpkg>] [--parameters <file>] [--decisions <file>] [--wait] [--url <url>]\n                                      upload the sealed package and ask for it to be installed; an admin approves.\n                                      --parameters answers the manifest's parameters by key; --decisions may only\n                                      decline grants: {\"grants\": {\"<package>\": {\"<grant key>\": \"declined\"}}}\n  deploy --sandbox [--file <afpkg>] [--no-arm]\n                                      install the package as its owner into the sandbox .agentflow/sandbox.json records,\n                                      or into a new one from sandbox.json when there is none or it is gone (sealing\n                                      package/ for you without --file), wait, secure the fields and save the profiles\n                                      sandbox.json's field_security names, and arm its triggers unless --no-arm.\n                                      Uploads sandbox.json's dependencies first. Deletes nothing: refuses a sandbox that\n                                      holds the package already, or that a changed sandbox.json no longer describes\n                                      (a change to field_security alone does not count)\n  deploy --sandbox --upgrade [--file <afpkg>] [--no-arm]\n                                      install a new version into the recorded sandbox, keeping its records and\n                                      settings; it sends the answers recorded when the sandbox was made, and applies\n                                      field_security as sandbox.json says it now. Raise version first, unless only\n                                      field_security changed. Then lists the objects the package retired that stay\n                                      installed as deprecated\n  deploy --sandbox --replace [--file <afpkg>] [--no-arm]\n                                      delete the recorded sandbox, naming it, then install into a new one from sandbox.json\n  publish [file] [--file <path>] [--url <url>] [--json]\n                                      publish a sealed package to the deployment's app catalog. Needs app_catalog.publish.\n  withdraw <prefix>/<slug>@<version> --reason <text> [--url <url>] [--json]\n                                      withdraw a version you published. Installations keep running; new setups cannot choose it.\n  sandbox check                       check sandbox.json without calling AgentFlow\n  sandbox create [--name <name>] [--ttl-days <n>]\n                                      make a sandbox from sandbox.json; its keys go to .agentflow/sandbox.json\n  sandbox list                        list your organization's live sandboxes\n  sandbox open --as <handle>          sign in to the sandbox in your browser as one of its people\n  sandbox mail-in --connection <key> --file <message.json>\n                                      deliver the message in the file to the sandbox's loopback connection <key>\n  sandbox mail-out --connection <key> list what the sandbox's loopback connection <key> sent, newest first\n  sandbox message-in --connection <key> --from <sender> [--thread-key <key>] [--text <text>] [--verified-email <address>]\n                     [--verified-phone <number>] [--file <path>]...\n                                      deliver a message to the sandbox's loopback connection <key> with a channel, on\n                                      the thread <key> names (the sender's own when absent); --verified-email and\n                                      --verified-phone mark the sender verified by that address or number, and each\n                                      --file is attached\n  sandbox message-in --connection <key> --text <text> [--thread-key <key>] [--verified-email <address>]\n                                      write as a visitor on the sandbox's chat connection <key>, in the chat this folder\n                                      keeps for the thread key (default when absent), opening one first when it has none\n                                      or it ended; --verified-email signs in the visitor with that address as the site would\n  sandbox message-out --connection <key>\n                                      list what Message steps sent on the sandbox's loopback connection <key> with a\n                                      channel, newest first\n  sandbox message-out --connection <key> [--thread-key <key>] [--follow]\n                                      print the chats message-in opened on the sandbox's chat connection <key>, or the one\n                                      --thread-key names, oldest first; --follow prints the thread's stream (default when\n                                      absent) as it comes, until the chat closes\n  sandbox records-in --connection <key> --stream <stream> --file <records.json>\n                                      record the file's ERP records on the sandbox's sandbox_erp connection <key>\n  sandbox records-out --connection <key>\n                                      list the bills apps wrote to the sandbox's sandbox_erp connection <key>, oldest first\n  sandbox record-status --connection <key> --external-ref <ref> --status <status>\n                                      set the status the bill written under <ref> reads back with: draft, posted or cancelled\n  sandbox record-remove --connection <key> --external-ref <ref>\n                                      remove the bill written under <ref>, so a read of it finds nothing and the next write\n                                      makes a new draft\n  sandbox fire --trigger <key>        fire the schedule trigger <key> now, as its cron would; its next occurrence stays\n  sandbox delete [--id <id>]          delete the sandbox in .agentflow/sandbox.json, or the one named\n  types [--out <file>] [--check]      write TypeScript for the package's objects (default src/generated/app.ts); --check only compares\n  status [--url <url>]                show this package's newest deployments and this folder's sandbox; reads only\n\nlint, deploy, status, publish and withdraw read AGENTFLOW_URL (the address you open AgentFlow at; --url overrides it) and AGENTFLOW_TOKEN\n(a service principal's key). sandbox and deploy --sandbox read AGENTFLOW_SANDBOX_KEY instead. No key is printed.\n\nEvery command takes --json: one JSON value on stdout, an error as {\"error\":{\"code\",\"message\"}}.\nExit codes: 0 done, 1 refused (lint: problems found; status: the newest deployment failed; deploy --wait: failed, cancelled or not approvable; deploy --sandbox: also\nstalled or not armed), 2 usage error, 130 deploy --wait or --sandbox stopped by Ctrl-C (the deployment stays).";
